function decisionContext(c){const a=state(c),v=c.surface.view||c.surface.id;if(v==='labyrinth-entry'&&!a.labActive)return 'Fresh expedition · Floor 1';if(v==='labyrinth-completion-choice')return 'Floor 3 · Completion';if(v==='labyrinth-endless-confirm')return 'Floor 3 · Before Endless';if(v==='labyrinth-boss-transform')return 'Floor '+a.labFloor+' · Boss reward';if(v==='labyrinth-sickness')return 'Floor '+a.labFloor+' · Sickness choice';return 'Floor '+a.labFloor+' · encounter '+a.labStep}
