function supportDetails(c){const a=state(c),x=c.data.supports.find(x=>x.id===a.supportInspect)||c.data.supports[0];return panel('Support focus','<span class="ux-eyebrow">'+h(c,x.type)+' · '+h(c,x.rarity)+'</span><h3>'+h(c,x.name)+'</h3><p>'+h(c,x.text)+'</p><div class="adv-stat-grid">'+stat(c,'Specialty',x.focus)+stat(c,'Training',x.trainingEffect+'%')+stat(c,'Energy saved',x.energySave)+stat(c,'Failure protection',(x.failureProtection*100).toFixed(1)+'%')+'</div><p class="ux-muted">Matching drills use this card. Bonds of 80% or more add friendship effects.</p>')}
