function shareMemory(c,m,r){const inventory=collectionState(c);if(!inventory)return;m.id=m.id||'reminiscence-review-memory-'+state(c).memories.length;let saved=inventory.memories.find(x=>x.id===m.id);if(!saved){saved={id:m.id,hero:'astra',name:m.name,rank:m.power>=98000?'S':m.power>=70000?'A':m.power>=44000?'B':'C',owner:'astra',condition:r.condition>=85?'Inspired':r.condition>=60?'Stable':r.condition>=35?'Tired':'Strained',stats:Object.assign({},m.stats),power:m.power,potentialPoints:m.pp};inventory.memories.forEach(x=>{if(x.owner==='astra')x.owner=''});inventory.memories.push(saved)}inventory.memoryEquipped.astra=m.id;inventory.selectedMemory=m.id;inventory.receipt={title:'Memory created',text:m.name+' was preserved and equipped to Astra.',error:false};c.state.hero='astra'}
function finalizeLabExtraction(c,reward){const a=state(c),pending=a.pendingLabExtraction;if(!pending||!reward||reward.id!==pending.rewardId||a.labExtracted)return false;a.labExtracted=pending.name;a.labActive=false;a.labLast=pending.name+' preserved as an Imprint.';a.pendingLabExtraction=null;record(c);return true}
