function newTraining(difficulty,preview=false){return {turn:preview?17:1,difficulty:difficulty||'Normal',energy:preview?42:100,condition:preview?63:75,mood:0,coins:preview?27:difficulty==='Nightmare'?52:difficulty==='Hard'?44:36,pp:preview?28:0,stats:preview?{Hp:76,Atk:84,Def:48,Spd:43,SkillPt:52}:{Hp:0,Atk:0,Def:0,Spd:0,SkillPt:0},bonds:Object.fromEntries(STARTERS.map((x,i)=>[x,preview?Math.min(100,53+i*6):25])),log:preview?['Sparring Breach cleared after turn 12.','Guard Drill completed.']:[],gates:preview?{12:'Cleared'}:{},last:preview?'Your route is ready to resume.':'The route has begun.'}}
