function drillPreview(c,id){const r=training(c),x=c.data.trainingActions.find(x=>x.id===id)||c.data.trainingActions[0],matching=c.data.supports.filter(x=>STARTERS.includes(x.id)&&x.focus===((c.data.trainingActions.find(a=>a.id===id)||{}).stat));const recovery=Math.min(24,Math.floor(c.data.supports.filter(x=>STARTERS.includes(x.id)).reduce((v,x)=>v+x.eventRecovery,0)/2));if(id==='rest')return {x,cost:0,gain:x.gain+recovery+Math.max(0,Math.floor((100-r.condition)/8)),fail:0,matching:[],friend:0,recovery};const cost=Math.max(1,x.energyCost-matching.reduce((v,x)=>v+x.energySave,0)),friend=matching.filter(x=>r.bonds[x.id]>=80).length,base=x.gain+matching.reduce((v,x)=>v+Math.max(1,Math.floor(x.bonus/2))+Math.floor(Math.max(0,x.specialtyPriority-8)/6),0),gain0=Math.max(1,Math.round(base*(1+matching.reduce((v,x)=>v+x.trainingEffect,0)/100+matching.filter(x=>r.bonds[x.id]>=80).reduce((v,x)=>v+x.friendshipBonus,0)/100))),dif=r.difficulty==='Nightmare'?.35:r.difficulty==='Hard'?.15:0,condition=r.condition>=85?.08:r.condition<35?-.1:0,gain=Math.max(1,Math.round(gain0*(1+dif+condition+r.mood*.04))),fail=clamp(clamp(.02+Math.max(0,45-r.energy)/45*.28+Math.max(0,cost-r.energy)/30*.35,.02,.65)-Math.min(.22,matching.reduce((v,x)=>v+x.failureProtection,0))+(r.difficulty==='Nightmare'?.1:r.difficulty==='Hard'?.05:0)+(r.condition>=85?-.025:r.condition>=60?0:r.condition>=35?.04:.1)-r.mood*.015,.01,.72);return {x,cost,gain,fail,matching,friend,recovery}}
