function drillDialog(c){const a=state(c),r=training(c),p=drillPreview(c,a.trainingAction),body='<div class="adv-choice-feature">'+c.icon(p.x.id==='rest'?'leaf':'sword')+'<h2>'+h(c,p.x.name)+'</h2><p>Expected gain <strong>+'+p.gain+' '+(p.x.id==='rest'?'internal energy':h(c,p.x.stat))+'</strong></p></div><div class="adv-stat-grid">'+stat(c,'Energy now',r.energy)+stat(c,'Cost',p.cost)+stat(c,'After action',Math.min(100,Math.max(0,r.energy-p.cost+(p.x.id==='rest'?p.gain:0))))+stat(c,'Failure',Math.round(p.fail*100)+'%')+'</div><p>'+ (p.x.id==='rest'?'Rest restores energy and condition. It still uses a turn.':p.matching.length+' matching support · '+p.friend+' friendship effect. Low energy raises failure risk; drills remain available.')+'</p><p>Completes turn '+r.turn+' of 48.</p>'+ (a.trainingOutcome?'<div class="adv-outcome" role="status">'+h(c,a.trainingOutcome)+'</div>':'');return dialog(c,'This turn’s action','Review the gain, cost and risk before committing.',body,go(c,'Back to route','reminiscence-run')+button(c,'Perform '+p.x.name,'drill-perform','',true,r.turn>48),trainingRun(c))}
