function completeRun(c){const a=state(c),r=a.training&&a.training.turn>48?a.training:(a.resultSnapshot||(a.resultSnapshot=Object.assign(newTraining(a.trainingDifficulty,true),{turn:49,energy:64,coins:40,pp:102,stats:{Hp:146,Atk:228,Def:173,Spd:145,SkillPt:214},gates:{12:'Cleared',24:'Cleared',36:'Cleared',48:'Cleared'}})));return r}
function trainingComplete(c){const a=state(c),r=completeRun(c),lead='<div class="adv-intro"><span class="ux-eyebrow">48 TURNS COMPLETE</span><h1>A Memory to carry forward.</h1><p>'+h(c,r.difficulty)+' · '+Object.values(r.gates).filter(x=>x==='Cleared').length+' / 4 gates cleared</p></div>',main=trainingStats(c,r)+panel('Route summary',stat(c,'Potential Points',r.pp)+'<p>Parent Memory: '+h(c,r.parentName||'none. This route began clean.')+'</p><p>The route becomes a permanent Memory after you confirm.</p>')+actions(go(c,'Review Memory','reminiscence-memory-create',true)+go(c,'Discard this route','reminiscence-discard-confirmation')),side=gates(c,r);return shell(c,'Reminiscence complete','Keep what Astra has learned.',layout(c,lead,main,side,hero(c,'astra','Astra Vale','MEMORY TRAINEE')),'reminiscence')}
function memoryDialog(c){const a=state(c),r=completeRun(c),created=a.createdMemory;return dialog(c,created?'Memory preserved':'Create this Memory?',created?'A permanent record of the completed route.':'This completes the current route.',created?'<div class="adv-choice-feature">'+c.icon('gem')+'<h2>'+h(c,created.name)+'</h2>'+pill(c,'Astra Vale')+'<p>'+h(c,created.difficulty)+' route · '+created.pp+' Potential Points</p></div>'+trainingStats(c,{stats:created.stats}):trainingStats(c,r)+'<p>Astra Vale · '+h(c,r.difficulty)+' · 48 turns · '+r.pp+' Potential Points.</p><p>Your existing Memories are preserved.</p>',created?go(c,'Return to preparation','reminiscence-setup',true)+go(c,'View Memory storage','storage-memories'):go(c,'Back','reminiscence-completion')+button(c,'Create Memory','memory-create','',true),trainingComplete(c))}
function discardDialog(c){const r=training(c);return dialog(c,'Discard this Reminiscence?','Your existing Memories stay.','<div class="adv-warning">'+c.icon('info')+'<h2>This route and its unclaimed Memory will be lost.</h2><p>Turn '+Math.min(r.turn,48)+' / 48 · '+r.pp+' Potential Points</p></div><p>Return Home instead to keep this run for later.</p>',go(c,'Keep run','reminiscence-run')+button(c,'Return Home · keep run','training-pause')+button(c,'Discard current route','training-discard'),trainingRun(c))}
function party(c){const a=state(c);return '<div class="adv-party">'+c.data.party.map((id,i)=>'<article class="adv-party-member '+(a.labHP[i]<=0?'is-fallen':'')+'">'+c.ui.portrait(id,'adv-party-portrait')+'<div><strong>'+h(c,c.data.heroes.find(x=>x.id===id).name)+'</strong><small>'+ (a.labHP[i]<=0?'Fallen':Math.round(a.labHP[i]*100)+'% HP')+'</small>'+meter(a.labHP[i]*100,100,'Party health')+'</div></article>').join('')+'</div>'}
function labLead(c){const a=state(c);return '<div class="adv-lab-status"><span class="ux-eyebrow">'+h(c,a.labDifficulty)+' · '+(a.labEndless?'ENDLESS':'WORLDROOT EXPEDITION')+'</span><h1>Floor '+a.labFloor+' <small>· '+Math.min(a.labStep,16)+' / 16</small></h1><div class="adv-lab-badges">'+pill(c,a.labEchoes+' Echoes')+pill(c,a.labAlignment==='None'?'Unaligned':a.labAlignment+' aligned')+(a.labEndless?pill(c,'Extraction waived','danger'):'')+'</div></div>'}
function labUnlocked(a,d){return d==='Normal'||d==='Hard'&&a.labNormalCleared||d==='Challenge'&&a.labHardCleared}
function labHub(c){const a=state(c),lead='<div class="adv-intro"><span class="ux-eyebrow">WORLDROOT EXPEDITION</span><h1>Follow the roots below.</h1><p>Three floors. Connected paths. Keep your party alive and bring one Imprint home.</p>'+pill(c,a.labKeys+' keys')+'<p class="ux-muted">One key per expedition. A free key recovers every 8 hours, up to 3.</p></div>';const cards='<div class="adv-lab-difficulties">'+DIFFICULTIES.map((d,i)=>{const unlocked=labUnlocked(a,d);return '<article class="adv-lab-difficulty '+(!unlocked?'is-locked':'')+'">'+c.icon(['leaf','sword','moon'][i])+'<span class="ux-eyebrow">'+(unlocked?'AVAILABLE':'LOCKED')+'</span><h2>'+d+'</h2><p>'+['Baseline combat. Standard rewards. No Sickness.','1.35× enemy base. 1.25× Echoes. Improved reward tiers.','Hard combat scale. 1.50× Echoes. A Sickness every floor.'][i]+'</p><small>'+(unlocked?'HP persists between encounters.':'Clear '+(d==='Hard'?'Normal':'Hard')+' Floor 3 first.')+'</small>'+button(c,a.labActive?'Resume current expedition':!unlocked?'View requirement':a.labKeys===0?'Need a key':'Prepare · 1 key','lab-prepare','data-id="'+d+'"',unlocked,false)+'</article>'}).join('')+'</div>';const notes=panel('A lasting skill','<p>Improve your existing skills during the run. After Floor 3, extract one portable Imprint or enter Endless.</p>'+go(c,'View expedition records','labyrinth-rankings'));const resume=a.labActive?panel('Expedition in progress','<p>'+h(c,a.labDifficulty)+' · Floor '+a.labFloor+' · encounter '+a.labStep+'</p>'+go(c,'Continue expedition','labyrinth-map',true)):'';return shell(c,'Labyrinth','Choose a difficulty, then commit one key.',layout(c,lead,cards+resume,notes,hero(c,'maelis','Worldroot expedition','BRANCHING PATHS · PERSISTENT HP')),'labyrinth')}
const ROOMS=['Monster','Event','Sanctuary','Elite','Shop','Angel','Monster','Event','Vault','Sanctuary','Elite','Demon','Shop','Monster','Elite','Boss'];
const roomIcon=t=>({Monster:'sword',Event:'star',Sanctuary:'heart',Elite:'shield',Shop:'coin',Angel:'sun',Demon:'moon',Vault:'chest',Boss:'crown'}[t]||'map');
function roomType(a,step,lane){let t=ROOMS[step-1];if(lane===1)t=step===16?'Boss':step%3===0?'Sanctuary':step%3===1?'Event':'Monster';if((a.labAlignment==='Angel'&&t==='Demon')||(a.labAlignment==='Demon'&&t==='Angel'))t='Event';return t}
function routeTrack(c,mini=false){const a=state(c),start=clamp(a.labWindow||Math.max(1,a.labStep-2),1,13),steps=mini?[Math.max(1,a.labStep-1),a.labStep,Math.min(16,a.labStep+1)]:Array.from({length:4},(_,i)=>start+i);return '<div class="adv-route-track '+(mini?'is-mini':'')+'">'+steps.map(step=>'<div class="adv-route-column"><small>ENCOUNTER '+String(step).padStart(2,'0')+'</small>'+(step===16?[0]:[0,1]).map(lane=>{const id=step+'-'+lane,type=roomType(a,step,lane),done=a.labCompleted.includes(id),skipped=a.labSkipped.includes(id),available=step===a.labStep&&!a.labCompleted.some(x=>x.startsWith(step+'-')),label=done?'Cleared':skipped?'Skipped':available?'Available':'Locked';return '<button type="button" class="adv-route-node '+(done?'is-cleared':skipped?'is-skipped':available?'is-available':'is-locked')+'" data-ui="adventures:lab-node" data-step="'+step+'" data-lane="'+lane+'" data-type="'+type+'" aria-label="'+h(c,type+', encounter '+step+', '+label)+'">'+c.icon(roomIcon(type))+'<strong>'+type+'</strong><span>'+label+'</span></button>'}).join('')+'</div>').join('')+'</div>'}
function labMap(c){const a=state(c),lead=labLead(c),route='<section class="adv-route-board"><div class="adv-section-heading"><h2>The connected route</h2>'+actions(button(c,'Earlier','lab-window','data-id="-4"')+button(c,'Current','lab-current')+button(c,'Later','lab-window','data-id="4"'))+'</div>'+routeTrack(c)+'<p class="ux-muted">Only a connected available room can be entered. Choosing a branch skips the other room.</p><div class="adv-last-result" role="status">'+h(c,a.labLast)+'</div></section>',side=panel('Your expedition party',party(c))+actions(go(c,'Leave expedition','labyrinth-leave-run'));let body;if(c.variant==='journey')body=lead+tabs(c,LABTABS,'labyrinth-map')+route+'<div class="adv-party-tray">'+party(c)+go(c,'Leave expedition','labyrinth-leave-run')+'</div>';else if(c.variant==='focus')body='<div class="adv-lab-focus"><aside>'+lead+tabs(c,LABTABS,'labyrinth-map')+side+'</aside><main><section class="adv-next-room"><span class="ux-eyebrow">NEXT DECISION</span><h2>Where will you lead them?</h2>'+routeTrack(c,true)+'</section>'+route+'</main></div>';else body=lead+tabs(c,LABTABS,'labyrinth-map')+'<div class="adv-lab-stage"><main>'+route+'</main><aside>'+side+'</aside></div>';return shell(c,'Labyrinth','Party health and run effects carry between rooms.',body,'labyrinth')}
function labSkills(c,extraction=false){const a=state(c);if(extraction){const inventory=collectionState(c);if(inventory)a.labCapacityFull=inventory.imprints.length>=12}const owner=c.data.heroes.find(x=>x.id===a.labHero)||c.data.heroes[0],skills=owner.skills.filter(x=>x.slot!=='Passive'),roster='<div class="adv-hero-tabs">'+c.data.party.map(id=>'<button type="button" data-ui="adventures:lab-hero" data-id="'+id+'" class="'+(a.labHero===id?'is-selected':'')+'">'+c.ui.portrait(id,'adv-small-portrait')+'<span>'+h(c,c.data.heroes.find(x=>x.id===id).name.split(' ')[0])+'</span></button>').join('')+'</div>';const rows=skills.map(s=>{const mods=modifiers(c,s.id),portable=mods.filter(x=>!x.runOnly);return '<article class="adv-skill-row '+(a.labSkill===s.id?'is-selected':'')+'"><div class="adv-skill-crest">'+c.icon(s.slot==='Ultimate'?'crown':s.slot==='Basic'?'sword':'star')+'</div><div class="adv-skill-copy"><small>'+h(c,s.slot)+' · '+h(c,owner.type)+'</small><h3>'+h(c,s.name)+'</h3><p>'+h(c,s.text)+'</p>'+mods.map(m=>'<div class="adv-modifier">'+pill(c,m.runOnly?'Run only':'Portable')+'<strong>'+h(c,m.name)+'</strong><span>'+h(c,m.text)+'</span>'+(m.downside?'<span class="adv-danger">'+h(c,m.downside)+'</span>':'')+'</div>').join('')+(mods.length?'':'<p class="ux-muted">No run modifiers yet.</p>')+'</div><aside>'+stat(c,'Power',s.power)+stat(c,'Cooldown',s.cooldown)+(extraction?button(c,a.labExtracted?'Extracted':a.labEndless?'Waived':a.labCapacityFull?'Choose replacement':'Extract this skill','lab-extract','data-id="'+s.id+'"',true,a.labDefeated||a.labExtracted||a.labEndless||!portable.length):button(c,'Inspect skill','lab-skill-select','data-id="'+s.id+'"'))+'</aside></article>'}).join('');const cap=panel(extraction?'Choose one portable skill':'Portable limits','<p>Per skill: three tunings, one boss transformation and one aligned effect. Run-only overcaps cannot be extracted.</p>'+ (extraction?(a.labEndless?'<p class="adv-danger">Endless permanently waived extraction for this run.</p>':a.labExtracted?'<p class="adv-outcome">'+h(c,a.labExtracted)+' preserved as an Imprint.</p>':'<p>The expedition ends after one extraction.</p>'):'')+go(c,'Imprint storage','storage-imprints'));const title=extraction?'Imprint extraction':'Expedition skills';return shell(c,title,extraction?'Carry one upgraded skill beyond the Worldroot.':'Your heroes’ real combat skills, improved by the route.',layout(c,labLead(c)+tabs(c,LABTABS,extraction?'':'labyrinth-skills'),roster+'<div class="adv-skills">'+rows+'</div>',cap,c.variant==='stage'?hero(c,owner.id,owner.name,extraction?'ONE SKILL TO PRESERVE':'EXPEDITION SKILL BUILD'):''),'labyrinth')}
function modifiers(c,id){const a=state(c);if(Object.prototype.hasOwnProperty.call(a.labModifiers,id))return a.labModifiers[id];return id==='astra_special_1'?[{name:'Focused Edge',text:'+12% power.',source:'Tuning',runOnly:false}]:[]}
function labEffects(c){const a=state(c),boons=a.labBoons.length?a.labBoons:[{name:'Memory Guard',text:'DEF +5%'}],body='<div class="adv-effect-groups">'+panel('Squad boons',boons.map(x=>'<article class="adv-effect"><span>'+c.icon('shield')+'</span><div><h3>'+h(c,x.name)+'</h3><p>'+h(c,x.text)+'</p><small>Active for this run</small></div></article>').join(''))+panel('Sickness',a.labSickness.length?a.labSickness.map(x=>'<article class="adv-effect"><span>'+c.icon('moon')+'</span><div><h3>'+h(c,x.name)+' · T'+x.tier+'</h3><p>'+h(c,x.text)+'</p></div></article>').join(''):empty(c,'No Sickness accepted','Normal and Hard have no mandatory floor Sickness. Challenge adds one each floor.'))+'</div>';return shell(c,'Run effects','Separate squad boons, Sickness and skill modifiers.',layout(c,labLead(c)+tabs(c,LABTABS,'labyrinth-effects'),body,panel('Alignment','<h3>'+h(c,a.labAlignment==='None'?'No alignment locked':a.labAlignment+' aligned')+'</h3><p>Accepting an offer locks your alignment. Opposite offers become events.</p>'+go(c,'Inspect skill modifiers','labyrinth-skills')),c.variant==='stage'?hero(c,'yselle','What the roots leave behind','BOONS & BURDENS'):''),'labyrinth')}
function labRankings(c){const a=state(c),filters=actions(DIFFICULTIES.map(d=>button(c,d,'lab-rank-filter','data-id="'+d+'"',a.labRankFilter===d||!a.labRankFilter&&d==='Normal')).join('')),rows=a.labRecords.filter(x=>x.difficulty===(a.labRankFilter||'Normal')),table=rows.length?'<div class="adv-records"><div class="adv-record-row"><strong>Commander</strong><span>Depth</span><span>Bosses</span><span>Turns</span></div>'+rows.map(x=>'<div class="adv-record-row"><strong>'+h(c,a.profileName)+' · YOU</strong><span>F'+x.floor+'-'+x.step+'</span><span>'+x.bosses+'</span><span>'+x.turns+'</span></div>').join('')+'</div>':empty(c,'An open record book','Finish or retire an expedition to record your personal best.',go(c,a.labActive?'Continue expedition':'Choose difficulty',a.labActive?'labyrinth-map':'labyrinth-hub',true));return shell(c,'Expedition records','Personal progress by difficulty.',layout(c,'<div class="adv-intro"><span class="ux-eyebrow">ENDLESS RECORDS</span><h1>How deep will you go?</h1><p>Placement rewards await server-authoritative rankings.</p></div>',filters+table,panel('Milestones','<p>First-clear rewards occur at floors 5, 10, 15, 20, then every fifth floor.</p><p>No placement rewards are fabricated in this preview.</p>'+go(c,'Return to Labyrinth','labyrinth-hub')),c.variant==='stage'?hero(c,'nerisse','Beyond the third floor','PERSONAL RECORDS'):''),'labyrinth')}
function choiceCard(c,title,text,action,attrs='',icon='star',disabled=false,tag=''){return '<article class="adv-choice-card"><span class="adv-choice-icon">'+c.icon(icon)+'</span>'+(tag?pill(c,tag):'')+'<h3>'+h(c,title)+'</h3><p>'+h(c,text)+'</p>'+button(c,disabled?'Unavailable':'Choose '+title,action,attrs,true,disabled)+'</article>'}
function labDialog(c,v){const live=state(c);if(['labyrinth-completion-choice','labyrinth-endless-confirm'].includes(v)&&live.labFloor<3)c={...c,state:{...c.state,adventures:{...live,labFloor:3,labStep:16,labWindow:13}}};const a=state(c);let title='',sub='',body='',footer='',parent=labMap(c);const selected=c.data.heroes.find(x=>x.id===a.labHero)||c.data.heroes[0],skills=selected.skills.filter(x=>x.slot!=='Passive');const choiceSkills=(action,description,kind)=>'<div class="adv-choice-grid">'+skills.slice(1,4).map(s=>{let mods=modifiers(c,s.id),cap=kind==='Boss'?mods.some(x=>x.source==='Boss'):kind==='Alignment'?mods.some(x=>x.source==='Angel'||x.source==='Demon'):mods.filter(x=>x.source==='Tuning'&&!x.runOnly).length>=3;return choiceCard(c,s.name,description,action,'data-id="'+s.id+'"',s.slot==='Ultimate'?'crown':'star',cap&&!a.labEndless,cap&&a.labEndless?'Run only':cap?'Portable cap':'Portable')}).join('')+'</div>';
 if(v==='labyrinth-entry'){
  const resuming=a.labActive;if(!resuming)c={...c,state:{...c.state,adventures:{...a,labFloor:1,labStep:1,labHP:c.data.party.map(()=>1)}}};
  title=resuming?'Resume '+a.labDifficulty+' Labyrinth?':'Enter '+a.labDifficulty+' Labyrinth?';sub=resuming?'Continue the committed expedition.':'One key starts a fresh expedition.';const unlocked=labUnlocked(a,a.labDifficulty);
  body=party(c)+'<div class="adv-stat-grid">'+stat(c,'Keys available',a.labKeys)+stat(c,'Entry',resuming?'Already committed':'1 key')+stat(c,'Floors',3)+'</div><p>'+(resuming?'Existing injuries and fallen heroes remain. No second entry key is consumed.':'All five heroes begin this fresh expedition at full HP. Each encounter resets cooldowns and Ultimate charge.')+'</p>'+(!unlocked?'<p class="adv-danger">Clear '+(a.labDifficulty==='Hard'?'Normal':'Hard')+' Floor 3 to unlock this difficulty.</p>':!resuming&&a.labKeys===0?'<p class="adv-danger">No keys. A free key recovers every eight hours, up to three.</p>':'');
  footer=go(c,'Back','labyrinth-hub')+button(c,resuming?'Resume expedition':'Enter expedition','lab-start','',true,!unlocked||(!resuming&&a.labKeys===0));parent=labHub(c)
 }
 else if(v==='labyrinth-node-choice'){title=a.labSelectedType||'Choose a connected room';sub='Floor '+a.labFloor+' · encounter '+a.labStep+' of 16';body=routeTrack(c,true)+'<p>'+h(c,a.labSelectedType?('Enter the '+a.labSelectedType+' room with your current HP. Other branches at this encounter will be skipped.'):'Select an available room on the route.')+'</p>';footer=go(c,'Inspect route','labyrinth-map')+button(c,'Enter room','lab-room-enter','',true,!a.labSelectedType)}
 else if(v==='labyrinth-encounter-ready'){title='Encounter ready';sub='Current HP carries into combat.';body=party(c)+'<p>Cooldowns and ultimate charge reset for this encounter. Fallen heroes remain fallen.</p>';footer=go(c,'Review party','labyrinth-map')+button(c,'Enter combat','lab-combat','',true)}
 else if(v==='labyrinth-fractured-event'){title='A Fractured Signal';sub='The route bends around an unstable memory.';body='<div class="adv-choice-grid">'+choiceCard(c,'Stabilize','Gain Memory Guard: DEF +5%. No fight.','lab-event','data-id="safe"','shield')+choiceCard(c,'Open the Cache','Gain more Echoes. A trapped cache may trigger an ambush.','lab-event','data-id="risk"','chest')+choiceCard(c,'Follow the Signal','Enter a fight for a larger Echo reward.','lab-event','data-id="hunt"','sword')+'</div>'}
 else if(v==='labyrinth-sanctuary'){title='Sanctuary';sub='Choose exactly one recovery rite.';const wounded=a.labHP.some(x=>x>0&&x<1),fallen=c.data.party.filter((id,i)=>a.labHP[i]<=0);body=party(c)+'<div class="adv-choice-grid">'+choiceCard(c,'Restore the Living','Heal living heroes for 30% max HP before Sickness adjustments.','lab-sanctuary','data-id="heal"','heart',!wounded)+(fallen.length?fallen.map(id=>choiceCard(c,'Revive '+c.data.heroes.find(x=>x.id===id).name,'Return this hero at 50% max HP.','lab-sanctuary','data-id="'+id+'"','plus')).join(''):choiceCard(c,'No Fallen Hero','Revival is unavailable.','lab-sanctuary','','plus',true))+'</div>'+ (a.labSickness.length?'<p class="adv-danger">Accepted Sickness may reduce healing. Inspect your current effects first.</p>':'');footer=go(c,'Inspect effects','labyrinth-effects')}
 else if(v==='labyrinth-alignment'){title=(a.labOfferAlignment||'Angel')+' Offer';sub='Accept an effect or leave your alignment unlocked.';body=actions(button(c,'Angel offer','lab-offer','data-id="Angel"',a.labOfferAlignment!=='Demon')+button(c,'Demon offer','lab-offer','data-id="Demon"',a.labOfferAlignment==='Demon'))+'<p>'+ (a.labOfferAlignment==='Demon'?'Blood Contract example: +30% power and +20 charge; lose 10% max HP on use.':'Grace Circuit example: +18% power, cooldown −1 and heal 8% max HP.')+'</p>'+choiceSkills('lab-align',a.labOfferAlignment==='Demon'?'A greater upside with an explicit skill downside.':'A major upside without a downside.','Alignment')+'<p>Opposite offers become events after you accept an alignment.</p>';footer=button(c,'Decline · keep alignment unlocked','lab-decline')}
 else if(v==='labyrinth-monster-reward'){title='Monster Spoils';sub='Choose one reward for this expedition.';body='<div class="adv-choice-grid">'+choiceCard(c,'Squad Boon','Gain a small permanent run stat bonus.','lab-monster','data-id="boon"','shield')+choiceCard(c,'Echo Cache','Gain Echoes to spend in future exchanges.','lab-monster','data-id="echoes"','coin')+'</div>'}
 else if(v==='labyrinth-elite-reward'){title='Elite Resonance';sub='Skill growth or a major squad boon.';body=choiceSkills('lab-tune','Add or tier up a portable tuning.','Tuning')+choiceCard(c,'Major Squad Boon','Take a large run-wide stat increase.','lab-major','','shield')}
 else if(v==='labyrinth-boss-transform'){title='Boss Core';sub=a.labEndless?'Overcap effects are run-only in Endless.':'Choose one transformative skill effect.';body=choiceSkills('lab-transform','Overdrive Form example: +22% power and +18 flat power.','Boss')}
 else if(v==='labyrinth-sickness'){title='Floor '+a.labFloor+' Sickness';sub='Choose one downside. It lasts for the rest of this run.';body='<div class="adv-choice-grid">'+[{id:'frail_1',name:'Frail Pulse',text:'Maximum HP is reduced by 8%.'},{id:'slowed_1',name:'Heavy Air',text:'Hero Speed is reduced by 5.'},{id:'echo_tax_1',name:'Echo Tithe',text:'Echo rewards are reduced by 15%.'}].map(x=>{let current=a.labSickness.find(s=>s.id===x.id);return choiceCard(c,x.name,x.text,'lab-sickness','data-id="'+x.id+'"','moon',!!current&&current.tier>=5,current?'T'+current.tier+' → T'+Math.min(5,current.tier+1):'New family')}).join('')+'</div><p class="adv-danger">Sickness accumulates across floors and remains active in Endless. Existing families can tier up to T5.</p>'}
 else if(v==='labyrinth-shop'){title='Wandering Exchange';sub='Spend Echoes on run power. Recovery is Sanctuary-exclusive.';body='<strong class="adv-echo-balance">'+a.labEchoes+' Echoes</strong><div class="adv-shop-offers">'+[{id:'stat1',name:'Tempered Formation',cost:28,text:'Small squad stat boon.'},{id:'stat2',name:'Rift Conditioning',cost:32,text:'Small squad stat boon.'},{id:'skill1',name:'Tune '+skills[1].name,cost:42,text:'Portable skill improvement.'},{id:'skill2',name:'Tune '+skills[2].name,cost:46,text:'Portable skill improvement.'},{id:'major',name:'Expedition Doctrine',cost:70,text:'Major run-wide buff.'}].map(x=>'<article class="adv-shop-offer"><div>'+c.icon(x.id.includes('skill')?'star':'shield')+'<h3>'+h(c,x.name)+'</h3><p>'+x.text+'</p></div><strong>'+x.cost+' Echoes</strong>'+button(c,a.labPurchased.includes(x.id)?'Purchased':a.labEchoes<x.cost?'Need more Echoes':'Purchase','lab-buy','data-id="'+x.id+'"',true,a.labPurchased.includes(x.id)||a.labEchoes<x.cost)+'</article>').join('')+'</div>';footer=button(c,'Leave exchange','lab-shop-leave')}
 else if(v==='labyrinth-completion-choice'){title='Floor 3 cleared';sub='Bring something home, or seek a deeper record.';body='<div class="adv-choice-grid">'+choiceCard(c,'Extract and End','Preserve one upgraded skill as a portable Imprint.','lab-extraction-open','','gem',a.labEndless)+choiceCard(c,'Enter Endless','Continue for personal records and permanently waive extraction for this run.','lab-endless-open','','crown')+'</div>'}
 else if(v==='labyrinth-endless-confirm'){title='Enter Endless?';sub='This decision cannot be reversed for this run.';body='<div class="adv-warning">'+c.icon('lock')+'<h2>Imprint extraction will be permanently disabled.</h2><p>Later bosses cannot restore it. Retire from Endless to record your result.</p></div>'+party(c);footer=go(c,'Keep extraction','labyrinth-completion-choice')+button(c,'Waive extraction · enter Endless','lab-endless-confirm','',true)}
 else if(v==='labyrinth-failed'){title='Expedition failed';sub='Your party was defeated.';body='<div class="adv-choice-feature">'+c.icon('shield')+'<h2>The key is consumed.</h2><p>No Imprint can be extracted from a defeated run.</p></div>'+stat(c,'Depth reached','F'+a.labFloor+'-'+Math.min(16,a.labStep));footer=button(c,'Return to Labyrinth','lab-failure-close','',true)}
 else if(v==='labyrinth-leave-run'){title=a.labEndless?'Retire from Endless?':'Abandon this expedition?';sub=a.labEndless?'Keep your depth record. Extraction remains waived.':'The entry key will not be returned.';body=party(c)+'<div class="adv-warning"><h3>'+ (a.labEndless?'Record F'+a.labFloor+'-'+a.labStep:'No Imprint will be extracted.')+'</h3><p>'+ (a.labEndless?'Your existing Imprints stay.':'Current skill tuning and route progress will be lost. Existing Imprints stay.')+'</p></div>';footer=go(c,'Keep exploring','labyrinth-map')+button(c,a.labEndless?'Retire and record':'Abandon expedition','lab-leave-confirm','',true)}
 if(!footer)footer=go(c,'Review route','labyrinth-map');return dialog(c,title,sub,body,footer,parent)
}
function profileCard(c){const a=state(c),home=c.state.home||{},level=home.accountLevel??8,clears=Math.max(0,(home.progress??8)-1);return '<article class="adv-profile-card frame-'+h(c,a.profileFrame)+'">'+c.ui.portrait(a.profileIcon,'adv-profile-portrait')+'<span class="ux-eyebrow">COMMANDER PROFILE</span><h2>'+h(c,a.profileName||'Commander')+'</h2><strong>'+h(c,a.profileTitle||'Rift Tester')+'</strong><p>'+h(c,a.profileBio||'Building a squad for Labyrinth clears and guild raids.')+'</p><div class="adv-stat-grid">'+stat(c,'Account level',level)+stat(c,'Campaign clears',clears)+'</div></article>'}
function profileForm(c){const a=state(c);return '<div role="form" class="adv-profile-form"><label>Username <small>Up to 18 characters</small><input maxlength="18" data-field="adventures.profileName" value="'+h(c,a.profileName)+'" autocomplete="off"></label><label>Title <small>Up to 28 characters</small><input maxlength="28" data-field="adventures.profileTitle" value="'+h(c,a.profileTitle)+'" autocomplete="off"></label><label>Bio <small>Up to 120 characters</small><textarea rows="3" maxlength="120" data-field="adventures.profileBio">'+h(c,a.profileBio)+'</textarea></label>'+actions(button(c,'Save player card','profile-save','',true))+(a.profileSaved?'<p class="adv-outcome" role="status">Player card updated in this review.</p>':'')+'</div>'}
function appearance(c){const a=state(c);return panel('Card appearance',actions(button(c,'Azure frame','profile-frame','data-id="azure"',a.profileFrame==='azure')+button(c,'Aurora frame','profile-frame','data-id="aurora"',a.profileFrame==='aurora'))+'<div class="adv-profile-icons">'+['astra','mika'].map(id=>'<button type="button" data-ui="adventures:profile-icon" data-id="'+id+'" class="'+(a.profileIcon===id?'is-selected':'')+'">'+c.ui.portrait(id,'adv-small-portrait')+'<span>'+h(c,c.data.heroes.find(x=>x.id===id).name)+'</span></button>').join('')+'</div>'+go(c,'Choose lobby hero in Roster','roster-growth'))}
function account(c){const lead='<div class="adv-intro"><span class="ux-eyebrow">PLAYER CARD</span><h1>Your place in Asterra.</h1><p>Edit the Commander profile attached to your local progress.</p></div>',links=panel('Account & preferences',actions(go(c,'Edit profile','account-profile-form')+go(c,'Preferences · design proposal','ui-settings')+go(c,'Recovery examples','save-recovery'))+'<p class="ux-muted">Preference and recovery actions in this study change only the example review state.</p>');let body;if(c.variant==='journey')body=lead+'<div class="adv-account-desk">'+profileCard(c)+'<div>'+appearance(c)+links+'</div></div>'+panel('Commander details',profileForm(c));else if(c.variant==='focus')body='<div class="adv-account-focus"><section>'+lead+profileForm(c)+appearance(c)+'</section><aside>'+profileCard(c)+links+'</aside></div>';else body=layout(c,lead,profileForm(c),appearance(c)+links,'<aside class="adv-account-identity">'+profileCard(c)+'</aside>');return shell(c,'Player card','Commander details and appearance.',body,'account')}
function profileDialog(c){return dialog(c,'Edit Commander details','Names and appearance stay together.',profileForm(c)+appearance(c),go(c,'Return to player card','account',true),account(c))}
function recovery(c){const a=state(c),cases={recovered:{title:'Your save was recovered',text:'A usable backup was found. Continue with the recovered account.',status:'Recovered backup',canNew:false},unreadable:{title:'Your saved data needs attention',text:'The existing save could not be read. Original files are preserved. An explicitly confirmed new local account is permitted in this case.',status:'Unreadable save',canNew:true},newer:{title:'This save needs a newer version',text:'The save format is newer than this client. Continuing with a temporary account could overwrite progress, so saving remains blocked.',status:'Newer-format save',canNew:false}};const x=cases[a.recoveryCase]||cases.recovered,fixtures='<div class="adv-fixture-bar"><span>Recovery example</span>'+actions(Object.entries({recovered:'Recovered',unreadable:'Unreadable',newer:'Newer format'}).map(([id,n])=>button(c,n,'recovery-case','data-id="'+id+'"',id===a.recoveryCase)).join(''))+'</div>';const body=fixtures+'<div class="adv-warning">'+c.icon(a.recoveryCase==='recovered'?'check':'lock')+'<h2>'+x.status+'</h2><p>'+x.text+'</p></div><div class="adv-preserved-files"><div>'+c.icon('shield')+'<strong>Original save</strong><span>Preserved</span></div><div>'+c.icon('shield')+'<strong>Backup files</strong><span>Preserved</span></div><div>'+c.icon('lock')+'<strong>Replacement</strong><span>Not written by this review</span></div></div>'+ (a.recoveryOutcome?'<p class="adv-outcome" role="status">'+h(c,a.recoveryOutcome)+'</p>':'');const footer=button(c,'Exit preview','recovery-exit')+(a.recoveryCase==='recovered'?button(c,'Continue recovered account','recovery-continue','',true):x.canNew?button(c,a.newAccountConfirm?'Confirm new local account preview':'Start new local account preview','recovery-new','',true):'');return dialog(c,x.title,'Blocking recovery state · example files are never modified.',body,footer,account(c))}
function artPreview(c){
 const a=state(c),owner=c.hero(),modes=['Basic','Active','Ultimate'],slotFor={Basic:'Basic',Active:'Active1',Ultimate:'Ultimate'},skill=owner.skills.find(s=>s.slot===slotFor[a.artSkill])||owner.skills.find(s=>s.slot==='Basic');
 const selected='<div class="adv-art-controls"><span class="ux-eyebrow">SELECTED PRESENTATION</span><h2>'+h(c,owner.name)+'</h2>'+actions(modes.map(x=>button(c,x,'art-skill','data-id="'+x+'"',a.artSkill===x)).join(''))+'<h3>'+h(c,skill.name)+'</h3><p>'+h(c,skill.text)+'</p><div class="adv-art-source">'+pill(c,owner.pixel?'Pixel battle sprite':'Illustration preview')+'<small>Presentation review only · no roster or kit acceptance is recorded.</small></div></div>';
 const stage='<div class="adv-battle-art-stage is-'+a.artSkill.toLowerCase()+'">'+(owner.pixel?c.ui.pixel(owner.id,'adv-preview-pixel'):c.ui.art(owner.id,'adv-preview-art'))+'<span class="adv-art-ring"></span><span class="adv-art-stage-label">'+h(c,a.artSkill)+' · '+h(c,skill.name)+'</span></div>';
 const roster='<div class="adv-art-roster">'+c.data.heroes.map(x=>'<button type="button" data-hero="'+x.id+'" aria-label="Preview '+h(c,x.name)+'" aria-pressed="'+(owner.id===x.id)+'">'+c.ui.portrait(x.id,'adv-small-portrait')+'<span>'+h(c,x.name.split(' ')[0])+'</span></button>').join('')+'</div>';
 const lead='<div class="adv-intro"><span class="ux-eyebrow">DEVELOPER REVIEW</span><h1>Character and skill presentation.</h1><p>Inspect an existing design. This review does not approve new art or gameplay kits.</p></div>';
 let body;
 if(c.variant==='journey'){const sequence='<nav class="adv-art-sequence" aria-label="Presentation sequence">'+modes.map((mode,i)=>{const k=owner.skills.find(x=>x.slot===slotFor[mode]);return '<button type="button" data-ui="adventures:art-skill" data-id="'+mode+'" aria-pressed="'+(mode===a.artSkill)+'"><b>0'+(i+1)+'</b><span><small>'+mode.toUpperCase()+'</small><strong>'+h(c,k.name)+'</strong><em>'+h(c,k.cooldown?'Base cooldown '+k.cooldown:'No cooldown')+'</em></span>'+c.icon(mode==='Ultimate'?'crown':'sword')+'</button>'}).join('')+'</nav>';body=lead+'<div class="adv-art-journey"><aside>'+sequence+'</aside><main>'+stage+'<section class="adv-art-caption"><span class="ux-eyebrow">'+h(c,owner.type)+' · '+h(c,owner.role)+'</span><h2>'+h(c,skill.name)+'</h2><p>'+h(c,skill.text)+'</p></section></main><aside class="adv-art-cast"><h3>Choose a hero</h3>'+roster+'</aside></div>'}
 else if(c.variant==='focus')body='<div class="adv-art-focus"><aside class="adv-art-cast"><span class="ux-eyebrow">NATIVE HERO DESIGNS</span><h2>Cast library</h2>'+roster+'</aside><main><div class="adv-art-focus-heading"><div><span class="ux-eyebrow">DEVELOPER REVIEW</span><h1>'+h(c,owner.name)+'</h1></div>'+pill(c,owner.rarity+' · '+owner.type)+'</div>'+stage+'<section class="adv-art-skill-ledger">'+owner.skills.map(k=>'<article><span>'+h(c,k.slot)+'</span><strong>'+h(c,k.name)+'</strong><small>'+h(c,k.cooldown?'Base CD '+k.cooldown:'No cooldown')+'</small></article>').join('')+'</section></main><aside>'+selected+'</aside></div>';
 else body=layout(c,lead,stage+roster,selected);
 return shell(c,'2D battle art review','Developer preview · separate from ordinary player navigation.',body,'account')
}
function settings(c,accessibility=false){
 const a=state(c),categories=['Audio','Presentation','Battle','Notifications'];
 const categoryButtons=categories.map(x=>button(c,x,'settings-tab','data-id="'+x+'"',a.settingsTab===x)).join('');
 let controls='';
 if(accessibility)controls='<h2>Read comfortably</h2><p class="ux-muted">Proposed preferences. These controls change only the review sample, not your device settings.</p><fieldset><legend>Text size</legend>'+actions(['Standard','Large'].map(x=>button(c,x,'preference','data-key="textSize" data-id="'+x+'"',a.textSize===x)).join(''))+'</fieldset><fieldset><legend>Motion</legend>'+actions(['Full','Reduced'].map(x=>button(c,x,'preference','data-key="motion" data-id="'+x+'"',a.motion===x)).join(''))+'</fieldset><fieldset><legend>Contrast</legend>'+actions(['Standard','High'].map(x=>button(c,x,'preference','data-key="contrast" data-id="'+x+'"',a.contrast===x)).join(''))+'</fieldset>';
 else if(a.settingsTab==='Audio')controls='<h2>Audio balance</h2><p class="ux-muted">Try visible values and reset behavior. This proposal does not change device audio.</p>'+[['bgm','Music'],['sfx','Sound effects'],['voice','Voice']].map(([id,n])=>'<label class="adv-slider">'+n+'<input type="range" min="0" max="100" data-field="adventures.'+id+'" value="'+a[id]+'"><output>'+a[id]+'%</output></label>').join('')+button(c,'Restore audio defaults','audio-reset');
 else if(a.settingsTab==='Presentation')controls='<h2>Character presentation</h2><fieldset><legend>Skill cut-ins</legend>'+actions(['Always','First time','Off'].map(x=>button(c,x,'preference','data-key="cutins" data-id="'+x+'"',a.cutins===x)).join(''))+'</fieldset>'+go(c,'Text, motion & contrast','ui-accessibility');
 else if(a.settingsTab==='Battle')controls='<h2>Battle readability</h2><p>Keep targeting indicators, cooldowns and health easy to inspect.</p>'+actions(go(c,'Review accepted combat layout','combat')+go(c,'Accessibility design','ui-accessibility'));
 else controls='<h2>Notifications</h2><p>Native notification permissions and delivery are not implemented by this review.</p><p>Proposed categories: designated farming recovery, Labyrinth key recovery and run reminders.</p>';
 const sample='<div class="adv-access-sample '+(a.textSize==='Large'?'is-large ':'')+(a.contrast==='High'?'is-high ':'')+(a.motion==='Reduced'?'is-reduced':'')+'"><span class="ux-eyebrow">READABILITY SAMPLE</span><h2>Where the Worldroot bends</h2><p>Choose a connected room. Your party’s current HP carries into the next encounter.</p>'+meter(72,100,'Sample health')+'<strong>72% HP</strong>'+actions(button(c,'Test selection','sample-select','',true))+(a.sampleSelected?'<p class="adv-outcome">Selection confirmed.</p>':'')+'</div>';
 const lead='<div class="adv-intro"><span class="ux-eyebrow">DESIGN PROPOSAL</span><h1>Make room for every player.</h1><p>Simple labels, visible values and a safe route back.</p></div>';
 let body;
 if(c.variant==='journey'&&accessibility)body=lead+'<section class="adv-accessibility-journey"><div class="adv-live-sample"><div><span class="ux-eyebrow">1 · TRY THE SAMPLE</span><h2>Judge the result as you change it.</h2><p>Text, motion and contrast choices stay visible together.</p></div>'+sample+'</div><div class="adv-preferences-choices">'+controls+'</div>'+go(c,'Return to player card','account')+'</section>';
 else if(c.variant==='journey')body=lead+'<div class="adv-preferences-journey"><aside class="adv-category-rail"><span class="ux-eyebrow">PREFERENCE GROUPS</span>'+categoryButtons+'<p>Proposed native preferences. All changes stay within this review.</p>'+go(c,'Player card','account')+'</aside><main><section class="adv-preferences-controls">'+controls+'</section><section class="adv-preferences-context"><div><span class="ux-eyebrow">CHECK THE RESULT</span><h3>Your place in the world stays clear.</h3><p>Keep a consistent sample beside the current group.</p></div>'+sample+'</section></main></div>';
 else if(c.variant==='focus')body='<div class="adv-preferences-focus"><aside>'+lead+sample+go(c,'Return to player card','account')+'</aside><main>'+(accessibility?'':'<nav class="adv-actions">'+categoryButtons+'</nav>')+'<section class="adv-preferences-controls">'+controls+'</section></main></div>';
 else body=layout(c,lead,(accessibility?'':actions(categoryButtons))+controls,sample+go(c,'Return to player card','account'));
 return shell(c,accessibility?'Accessibility proposal':'Preferences proposal','Proposed native controls · changes affect this review sample only.',body,'account')
}
function onboarding(c){
 const a=state(c),steps=[['A company worth knowing.','Meet your heroes, read their direct skill effects and assemble five for the road.','roster-growth','Meet the roster'],['A place for everyone.','Prepare five heroes in nine fixed cells before battle. Entering combat freezes the formation.','campaign-normal','Choose your first encounter'],['Keep the discoveries.','Reminiscence creates Memories. Labyrinth extracts skill Imprints. Each has its own run rules.','reminiscence-setup','See Reminiscence']],index=clamp(Number(a.onboardStep)||0,0,2),x=steps[index],guide=c.data.heroes.find(h=>h.id===['astra','adela','yselle'][index]);
 const lead='<div class="adv-intro"><span class="ux-eyebrow">'+(index+1)+' / 3 · DESIGN PROPOSAL</span><h1>'+x[0]+'</h1><p>'+x[1]+'</p></div>';
 const stepper='<nav class="adv-lesson-progress" aria-label="Introduction steps">'+steps.map((step,i)=>'<button type="button" data-ui="adventures:onboard-step" data-id="'+i+'" aria-current="'+(i===index?'step':'false')+'"><b>0'+(i+1)+'</b><span>'+['Know the company','Prepare the formation','Keep the rewards'][i]+'</span>'+c.icon(i<index?'check':i===index?'arrow':'chevron')+'</button>').join('')+'</nav>';
 let lesson;
 if(index===0){const owner=c.hero(),passive=owner.skills.find(k=>k.slot==='Passive'),basic=owner.skills.find(k=>k.slot==='Basic');lesson='<section class="adv-roster-lesson"><div class="adv-lesson-hero">'+c.ui.art(owner.id)+'<span>'+h(c,owner.name)+'</span></div><div class="adv-lesson-dossier"><span class="ux-eyebrow">HERO DOSSIER · EXISTING NATIVE HERO</span><h2>'+h(c,owner.name)+'</h2><p>'+h(c,owner.type)+' · '+h(c,owner.role)+'</p>'+c.ui.stats(owner)+'<article><span>Passive</span><h3>'+h(c,passive.name)+'</h3><p>'+h(c,passive.text)+'</p></article><article><span>Basic</span><h3>'+h(c,basic.name)+'</h3><p>'+h(c,basic.text)+'</p></article></div></section>'}
 else if(index===1){const grid=c.state.home?.formation||['astra',null,'adela',null,'maelis',null,'yselle',null,'nerisse'];lesson='<section class="adv-formation-lesson"><div><span class="ux-eyebrow">NINE FIXED CELLS · FIVE HEROES</span><div class="adv-lesson-depth"><span>Rear</span><span>Center</span><span>Front</span></div><div class="adv-lesson-grid">'+grid.map((id,i)=>'<div><small>'+['Rear','Center','Front'][i%3]+' · '+(Math.floor(i/3)+1)+'</small>'+(id?c.ui.portrait(id)+'<strong>'+h(c,c.data.heroes.find(x=>x.id===id).name.split(' ')[0])+'</strong>':'<span>Empty cell</span>')+'</div>').join('')+'</div></div><aside><h2>Place before you depart.</h2><p>Choose a hero, then a cell. An occupied cell swaps the two heroes.</p><p>The same 3×3 cells carry into battle. Formation controls disappear once the encounter begins.</p><strong>Keep the existing Front/Back gameplay rules.</strong></aside></section>'}
 else lesson='<section class="adv-reward-lesson"><article>'+c.icon('book')+'<span class="ux-eyebrow">REMINISCENCE</span><h2>A permanent Memory</h2><p>Finish a 48-turn route, review its result and create the Memory explicitly. Existing saved Memories survive discarding a later route.</p>'+go(c,'Preview Reminiscence','reminiscence-setup')+'</article><article>'+c.icon('gem')+'<span class="ux-eyebrow">LABYRINTH</span><h2>A portable Imprint</h2><p>Extract one eligible activated skill after completion. Equipped and favorite records are protected; a full library needs deliberate replacement.</p>'+go(c,'Preview the protected library','imprint-library-management')+'</article></section>';
 const next=actions(go(c,x[3],x[2],true)+button(c,index===2?'Restart guide':'Next step','onboard-next')+go(c,'Explore Home','home'));
 const context=panel('Progress without pressure','<p>Campaign and story do not use account energy. Only explicitly designated farming stages do.</p>');
 let body;
 if(c.variant==='focus')body='<div class="adv-onboarding-focus"><aside>'+lead+stepper+context+'</aside><main><header><span class="ux-eyebrow">TRY THE CURRENT GAME LOOP</span><h2>'+['Read a real hero kit','See the accepted formation','Know what you keep'][index]+'</h2></header>'+lesson+'<footer>'+next+'</footer></main></div>';
 else if(c.variant==='journey')body=lead+stepper+'<div class="adv-onboarding-journey"><main>'+lesson+next+'</main><aside>'+context+'</aside></div>';
 else body=layout(c,lead,stepper+next,context,hero(c,guide.id,['Meet the company','Prepare the journey','Carry it forward'][index],'FIRST STEPS'));
 return shell(c,'First steps proposal','A proposed introduction using existing heroes, formation and reward rules.',body,'home')
}
function storyArchive(c){
 const a=state(c),home=c.state.home||{},progress=home.progress??8,chapterId=clamp(Number(a.archiveChapter)||1,1,c.data.chapters.length),chapter=c.data.chapters.find(x=>x.id===chapterId)||c.data.chapters[0],read=a.archiveReadTitles||[];
 const entries=c.data.storyFlags.filter(x=>Math.ceil(x.stageId/24)===chapterId).map((x,i)=>{const locked=x.stageId>progress||(x.stageId===progress&&['PostBattle','ChapterClear'].includes(x.trigger)),seen=read.includes(x.title)||(home.storyRead&&x.title===c.data.storyExample.title);return {...x,index:i,state:locked?'Locked':seen?'Read':'Unread',number:((x.stageId-1)%24)+1,hero:i%3===0?'astra':i%3===1?'yselle':'adela'}});
 const visible=entries.filter(x=>a.archiveFilter==='All'||x.state===a.archiveFilter),selected=entries.find(x=>x.title===a.archiveEntry)||visible[0]||entries[0];
 const filters=actions(['All','Unread','Read','Locked'].map(x=>button(c,x,'archive-filter','data-id="'+x+'"',a.archiveFilter===x)).join(''));
 const rows=visible.map(x=>'<article class="adv-story-row '+(x.title===selected?.title?'is-selected':'')+'">'+'<span class="adv-archive-seal">'+c.icon('story')+'</span><div><small>'+x.state+' · '+chapterId+'-'+x.number+' · '+h(c,x.trigger)+'</small><h3>'+h(c,x.title)+'</h3><p>'+h(c,x.state==='Locked'?'Clear the required story stage to reach this scene.':x.state==='Read'?'A scene already marked read in this proposal.':'An authored scene waiting in the chapter.')+'</p></div>'+button(c,x.state==='Locked'?'Locked':'Review entry','archive-read','data-title="'+h(c,x.title)+'"',x.state==='Unread',x.state==='Locked')+'</article>').join('')||empty(c,'No '+a.archiveFilter.toLowerCase()+' scenes in this chapter','Choose another filter or chapter.',button(c,'Show all scenes','archive-filter','data-id="All"',true));
 const detail=selected?'<section class="adv-archive-detail"><span class="ux-eyebrow">SELECTED SCENE · '+selected.state.toUpperCase()+'</span><h2>'+h(c,selected.title)+'</h2><p>'+h(c,chapter.name)+' · '+chapterId+'-'+selected.number+'</p>'+pill(c,selected.trigger)+'<p>Titles and stage associations use the authored story catalogue. This archive and its read markers are proposed presentation only.</p>'+(selected.title===c.data.storyExample.title?go(c,'Open available story scene','story-reader',true):selected.state==='Locked'?'<p class="adv-danger">This entry remains locked at the current example progress.</p>':button(c,'Mark read in this proposal','archive-mark-read','data-title="'+h(c,selected.title)+'"',true))+'</section>':'';
 const lead='<div class="adv-intro"><span class="ux-eyebrow">DESIGN PROPOSAL</span><h1>The story so far.</h1><p>An archive of authored scene titles. Reading remains separate from stage clearing and first-clear rewards.</p></div>';
 const chapterPicker='<label class="adv-archive-chapter-select">Chapter<select data-field="adventures.archiveChapter">'+c.data.chapters.map(ch=>'<option value="'+ch.id+'"'+(ch.id===chapterId?' selected':'')+'>'+ch.id+' · '+h(c,ch.name)+'</option>').join('')+'</select></label>';
 let body;
 if(c.variant==='journey')body=lead+'<div class="adv-archive-journey"><nav class="adv-archive-chapters" aria-label="Story chapters">'+c.data.chapters.map(ch=>'<button type="button" data-ui="adventures:archive-chapter" data-id="'+ch.id+'" aria-pressed="'+(ch.id===chapterId)+'"><b>'+String(ch.id).padStart(2,'0')+'</b><span>'+h(c,ch.name)+'</span></button>').join('')+'</nav><main><header><span class="ux-eyebrow">CHAPTER '+String(chapterId).padStart(2,'0')+'</span><h2>'+h(c,chapter.name)+'</h2><p>'+h(c,chapter.region)+'</p></header>'+filters+'<div class="adv-archive-episodes">'+rows+'</div></main><aside>'+detail+'</aside></div>';
 else if(c.variant==='focus')body='<div class="adv-archive-focus"><aside>'+lead+chapterPicker+panel('Continue the journey','<p>Current example: '+Math.ceil(progress/24)+'-'+(((progress-1)%24)+1)+'. Read-state changes here never grant clear rewards.</p>')+go(c,'Return to Campaign','campaign-normal')+'</aside><main>'+filters+'<div class="adv-archive-ledger">'+rows+'</div>'+detail+'</main></div>';
 else body=layout(c,lead,chapterPicker+filters+rows,detail+go(c,'Return to Campaign','campaign-normal'));
 return shell(c,'Story archive proposal','Authored scene catalogue · proposed archive navigation and read markers.',body,'home')
}
function finishLab(c,message){const a=state(c);a.labLast=message;const id=a.labSelected||a.labStep+'-0';if(!a.labCompleted.includes(id))a.labCompleted.push(id);const other=a.labStep+'-'+(id.endsWith('-0')?'1':'0');if(a.labStep<16&&!a.labSkipped.includes(other))a.labSkipped.push(other);a.labSelected='';a.labSelectedType='';if(a.labStep>=16){if(a.labFloor===3&&!a.labEndless){if(a.labDifficulty==='Normal')a.labNormalCleared=true;if(a.labDifficulty==='Hard')a.labHardCleared=true;c.route('labyrinth-completion-choice');return}a.labFloor++;a.labStep=1;a.labWindow=1;if(a.labDifficulty==='Challenge'){c.route('labyrinth-sickness');return}}else a.labStep++;a.labWindow=clamp(a.labStep-1,1,13);c.route('labyrinth-map')}
